11	use Illuminate\Http\JsonResponse;
12	
13	class InsightController extends Controller
14	{
15	    /**
16	     * Get area insights with optional bbox filter and underserved hotspot detection.
17	     *
18	     * Query params:
19	     * - bbox (string):  "minLng,minLat,maxLng,maxLat"  e.g. "110.3,-7.8,110.5,-7.6"
20	     * - bbox (array):   bbox[minLng]=&bbox[minLat]=&bbox[maxLng]=&bbox[maxLat]=
21	     */
22	    public function area(): JsonResponse
23	    {
24	        $minLng = $minLat = $maxLng = $maxLat = null;
25	        $hasBbox = false;
26	
27	        $raw = request()->input('bbox');
28	        if ($raw !== null && $raw !== '') {
29	            if (is_string($raw)) {
30	                $parts = explode(',', $raw);
31	                if (count($parts) === 4) {
32	                    [$minLng, $minLat, $maxLng, $maxLat] = array_map('floatval', $parts);
33	                    $hasBbox = true;
34	                }
35	            } elseif (is_array($raw)) {
36	                $minLng = (float) ($raw['minLng'] ?? $raw[0] ?? 0);
37	                $minLat = (float) ($raw['minLat'] ?? $raw[1] ?? 0);
38	                $maxLng = (float) ($raw['maxLng'] ?? $raw[2] ?? 0);
39	                $maxLat = (float) ($raw['maxLat'] ?? $raw[3] ?? 0);
40	                $hasBbox = true;
41	            }
42	        }
43	
44	        // ---- Stats with optional bbox filter ----
45	        $poiQuery = Poi::query();
46	        if ($hasBbox) {
47	            $poiQuery->whereBetween('latitude', [$minLat, $maxLat])
48	                     ->whereBetween('longitude', [$minLng, $maxLng]);
49	        }
50	
51	        $stats = [
52	            'poi_count_by_category' => Category::withCount(['pois' => function ($q) use ($hasBbox, $minLat, $minLng, $maxLat, $maxLng) {
53	                if ($hasBbox) {
54	                    $q->whereBetween('latitude', [$minLat, $maxLat])
55	                      ->whereBetween('longitude', [$minLng, $maxLng]);
56	                }
57	            }])->get()->pluck('pois_count', 'name'),
58	
59	            'average_transit_friendliness' => (float) (clone $poiQuery)->avg('transit_friendliness_score'),
60	            'total_transit_stops'          => TransitStop::count(),
61	            'total_transit_routes'         => TransitRoute::count(),
62	            'data_sources'                 => DataSource::pluck('name'),
63	        ];
64	
65	        // ---- Underserved hotspots ----
66	        // Cari POI dengan jarak ke halte > 500m (dari poi_transit_stops) ATAU transit_friendliness_score < 6
67	        $underservedQuery = Poi::select('id', 'name', 'latitude', 'longitude', 'transit_friendliness_score');
68	
69	        if ($hasBbox) {
70	            $underservedQuery->whereBetween('latitude', [$minLat, $maxLat])
71	                             ->whereBetween('longitude', [$minLng, $maxLng]);
72	        }
73	
74	        $underservedHotspots = $underservedQuery
75	            ->where(function ($q) {
76	                // Kondisi underserved: skor rendah, atau tidak ada stop terdekat, atau jarak > 500m
77	                $q->whereNull('transit_friendliness_score')
78	                  ->orWhere('transit_friendliness_score', '<', 6)
79	                  ->orWhereRaw('NOT EXISTS (SELECT 1 FROM poi_transit_stops WHERE poi_id = pois.id)')
80	                  ->orWhereRaw('COALESCE((SELECT MIN(distance_meters) FROM poi_transit_stops WHERE poi_id = pois.id), 999999) > 500');
81	            })
82	            ->orderBy('transit_friendliness_score', 'asc')
83	            ->limit(10)
84	            ->get();
85	
86	        return response()->json([
87	            'success' => true,
88	            'data' => array_merge($stats, [
89	                'underserved_hotspots' => $underservedHotspots,
90	                'ai_insight' => 'Kawasan Malioboro sampai Kotagede memiliki kerapatan POI tertinggi dengan rata-rata jarak ke halte 280 meter. Area Ring Road Utara hingga Jalan Kaliurang memiliki skor transit di bawah 5.0 — perlu prioritas pengembangan.',
91	            ]),
92	        ]);
93	    }
94	}
