14	
15	class ItineraryController extends Controller
16	{
17	    public function store(Request $request): JsonResponse
18	    {
19	        $validated = $request->validate([
20	            'session_token' => 'required|string|max:100',
21	            'poi_ids' => 'required|array|min:1|max:10',
22	            'poi_ids.*' => 'exists:pois,id',
23	        ]);
24	
25	        $pois = Poi::with('transitStops', 'category')->whereIn('id', $validated['poi_ids'])->get();
26	
27	        // Simple route optimizer: sort by transit score desc then by proximity
28	        $ordered = $pois->sortByDesc('transit_friendliness_score')->values();
29	
30	        $itinerary = Itinerary::create([
31	            'session_token' => $validated['session_token'],
32	            'title' => 'Trip: ' . $ordered->first()->name . ' → ' . $ordered->last()->name,
33	            'total_estimated_minutes' => $ordered->count() * 60,
34	            'share_slug' => 'trip-' . Str::random(8),
35	        ]);
36	
37	        $items = [];
38	        foreach ($ordered as $i => $poi) {
39	            $nearestStop = $poi->transitStops->sortBy('pivot.distance_meters')->first();
40	            $items[] = ItineraryItem::create([
41	                'itinerary_id' => $itinerary->id,
42	                'poi_id' => $poi->id,
43	                'visit_order' => $i + 1,
44	                'suggested_transit_stop_id' => $nearestStop?->id,
45	                'estimated_arrival_time' => sprintf('%02d:00', 8 + $i * 2),
46	            ]);
47	        }
48	
49	        // --- Generate AI narrative ---
50	        $poiData = $ordered->map(fn(Poi $p) => [
51	            'name' => $p->name,
52	            'category_name' => $p->category?->name ?? 'Umum',
53	            'transit_score' => $p->transit_friendliness_score ?? 5,
54	        ])->toArray();
55	
56	        $ai = app(AIService::class);
57	        $narrative = $ai->generateItineraryNarrative($poiData);
58	
59	        // --- Fallback: route-optimizer-based narrative if AI returned empty ---
60	        if (empty(trim($narrative))) {
61	            $optimizer = app(RouteOptimizerService::class);
62	            $routePois = $ordered->map(fn(Poi $p) => [
63	                'latitude' => (float) $p->latitude,
64	                'longitude' => (float) $p->longitude,
65	                'name' => $p->name,
66	            ])->toArray();
67	            $optimized = $optimizer->optimizeOrder($routePois);
68	            $names = collect($optimized)->pluck('name');
69	            $narrative = "Mulai perjalanan dari **{$names->first()}**, lanjut menjelajahi " .
70	                         $names->slice(1, -1)->implode(', ') .
71	                         ", dan akhiri di **{$names->last()}**. " .
72	                         "Setiap lokasi bisa dijangkau dengan Trans Jogja dalam jarak jalan kaki yang nyaman.";
73	        }
74	
75	        $itinerary->update(['ai_narrative' => $narrative]);
76	        $itinerary->load('items.poi', 'items.suggestedTransitStop');
77	
78	        return response()->json(['success' => true, 'data' => $itinerary], 201);
79	    }
80	
81	    public function show(string $slug): JsonResponse
82	    {
83	        $itinerary = Itinerary::with('items.poi', 'items.suggestedTransitStop')
84	            ->where('share_slug', $slug)->first();
