3	namespace App\Services;
4	
5	class RouteOptimizerService
6	{
7	    /**
8	     * Sort POIs for optimal visiting order.
9	     * Uses nearest-neighbor heuristic: start from first, keep picking closest.
10	     */
11	    public function optimizeOrder(array $pois): array
12	    {
13	        if (count($pois) <= 2) {
14	            return $pois;
15	        }
16	
17	        $ordered = [$pois[0]];
18	        $remaining = array_slice($pois, 1);
19	
20	        while (!empty($remaining)) {
21	            $last = end($ordered);
22	
23	            $nearestIdx = null;
24	            $nearestDist = PHP_FLOAT_MAX;
25	
26	            foreach ($remaining as $idx => $candidate) {
27	                $dist = $this->distance(
28	                    $last['latitude'], $last['longitude'],
29	                    $candidate['latitude'], $candidate['longitude']
30	                );
31	                if ($dist < $nearestDist) {
32	                    $nearestDist = $dist;
33	                    $nearestIdx = $idx;
34	                }
35	            }
36	
37	            $ordered[] = $remaining[$nearestIdx];
38	            array_splice($remaining, $nearestIdx, 1);
39	        }
40	
41	        return $ordered;
42	    }
43	
44	    /**
45	     * Reorder and attach transit info.
46	     * Returns array of [poi, nearest_stop, distance_meters, walking_minutes]
47	     */
48	    public function buildRoute(array $pois, array $allStops): array
49	    {
50	        $ordered = $this->optimizeOrder($pois);
51	        $transitScore = new TransitScoreService();
52	
53	        $route = [];
54	        foreach ($ordered as $poi) {
55	            $nearest = null;
56	            $minDist = PHP_FLOAT_MAX;
57	
58	            foreach ($allStops as $stop) {
59	                $dist = $this->distance(
60	                    $poi['latitude'], $poi['longitude'],
61	                    $stop['latitude'], $stop['longitude']
62	                );
63	                if ($dist < $minDist) {
64	                    $minDist = $dist;
65	                    $nearest = $stop;
66	                }
67	            }
68	
69	            $route[] = [
70	                'poi' => $poi,
71	                'nearest_stop' => $nearest,
72	                'distance_meters' => (int) $minDist,
73	                'walking_minutes' => $transitScore->walkingMinutes((int) $minDist),
74	            ];
75	        }
76	
77	        return $route;
78	    }
79	
80	    private function distance(float $lat1, float $lng1, float $lat2, float $lng2): float
81	    {
82	        $dLat = deg2rad($lat2 - $lat1);
83	        $dLng = deg2rad($lng2 - $lng1);
84	        $a = sin($dLat / 2) ** 2 + cos(deg2rad($lat1)) * cos(deg2rad($lat2)) * sin($dLng / 2) ** 2;
85	        return 2 * atan2(sqrt($a), sqrt(1 - $a));
86	    }
87	}
